evaluation.command:
bun -e '
import { Effect, Schema } from "effect"
import { AppNodeBuilder } from "./src/effect/app-node-builder"
import { ModelsDev } from "./src/models-dev"
import { Model } from "./src/model"
import { Global } from "@opencode/util/global"
import { tempGlobalLayer } from "./test/fixture/global"
const layer = AppNodeBuilder.build(ModelsDev.configured({ file: "/var/tmp/redcode-models-v2-current.json", fetch: false, snapshot: false }), [Global.node.replace(tempGlobalLayer)])
await Effect.runPromise(Effect.gen(function* () {
 const catalog = yield* ModelsDev.Service
 const providers = yield* catalog.get()
 const models = providers.flatMap((provider) => provider.models)
 for (const model of models) Schema.decodeUnknownSync(Model.Info)(Schema.encodeSync(Model.Info)(model))
 console.log(JSON.stringify({ providers: providers.length, models: models.length, eligibleChatModels: models.filter((model) => model.enabled).length, selectedProtocols: Object.fromEntries([...new Set(models.map((model) => model.catalog?.protocol).filter(Boolean))].map((protocol) => [protocol, models.filter((model) => model.catalog?.protocol === protocol).length])), knownTokenCosts: models.filter((model) => model.cost.length).length, digest: models[0]?.catalog?.digest, schemaRoundTrips: models.length }))
}).pipe(Effect.scoped, Effect.provide(layer)))
' > /var/tmp/redcode-catalog-live-v2-evaluation-complete.log 2>&1
